package com.example.starter.firmware.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 开始回滚演练请求。
 * 规范设备集合 deviceIds 必须非空且不重复；开始时刻由服务端统一时钟生成（UTC），不由客户端指定。
 *
 * @param requestId       幂等请求ID
 * @param operator        操作者，纳入幂等指纹
 * @param model           规范设备型号
 * @param targetVersion   目标版本（待发布版本），设备开始时必须处于该版本
 * @param rollbackVersion 回退版本（正式投放来源版本），必须与目标版本不同
 * @param deviceIds       规范设备ID集合，至少一台
 */
public record StartRehearsalRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String operator,
        @NotBlank @Size(max = 64) String model,
        @NotBlank @Size(max = 64) String targetVersion,
        @NotBlank @Size(max = 64) String rollbackVersion,
        @NotEmpty List<@NotBlank @Size(max = 64) String> deviceIds) {
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.ReceiptResult;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 提交回滚演练结果请求。必须一次性提交与演练规范集合完全一致的每台设备结果，
 * 服务端先校验完整最终状态，再在同一事务内批量落库；校验失败不产生任何终态或门禁。
 *
 * @param requestId 幂等请求ID
 * @param operator  结果提交操作者（门禁授予操作者），纳入幂等指纹
 * @param results   每台设备的回退结果，集合须与开始时规范集合完全相等
 */
public record CompleteRehearsalRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String operator,
        @NotEmpty @Valid List<@Valid DeviceResultInput> results) {

    /**
     * 单台设备回退结果。FAILED 时 failureReason 必填；SUCCESS 时忽略该字段。
     */
    public record DeviceResultInput(
            @NotBlank @Size(max = 64) String deviceId,
            @NotNull ReceiptResult result,
            @Size(max = 256) String failureReason) {
    }
}

