    @Test
    void 存在失败结果_演练FAILED不给门禁_设备不回退_可重新演练() throws Exception {
        register("rd1", "d1", "m1", "2.0.0", 1);
        register("rd2", "d2", "m1", "2.0.0", 2);
        long rehearsalId = idOf(startRehearsal("""
                {"requestId":"rs1","operator":"alice","model":"m1","targetVersion":"2.0.0",
