        mockMvc.perform(post("/api/rehearsals/9999/results").contentType("application/json")
                        .content("""
                                {"requestId":"rc9","operator":"alice","results":[{"deviceId":"d1","result":"SUCCESS"}]}
                                """))
                .andExpect(status().isNotFound());
        assertThat(releaseId).isPositive();
    }
